type Props = { role: 'USER' | 'ADMIN'; approve: () => void }
export const ApproveButton = ({ role, approve }: Props) =>
  role === 'ADMIN' ? <button onClick={approve}>승인</button> : null

type Props = { data?: { id: string; name: string }[]; isLoading: boolean; error?: unknown; refetch: () => void }
export const LeaveList = ({ data, isLoading }: Props) => {
  if (isLoading) return <p>불러오는 중</p>
  const leaves = data ?? []
  if (leaves.length === 0) return <p>등록된 휴가가 없습니다.</p>
  return <ul>{leaves.map((leave) => <li key={leave.id}>{leave.name}</li>)}</ul>
}

it('네트워크 장애에서도 목록을 보여 준다', () => {
  render(<LeaveList data={undefined} isLoading={false} error={{ status: 'FETCH_ERROR' }} refetch={vi.fn()} />)
  expect(screen.getByText('등록된 휴가가 없습니다.')).toBeInTheDocument()
})

type Props = { connected: boolean; reconnect: () => void }
export const ConnectionNotice = ({ connected, reconnect }: Props) =>
  connected ? null : <div role="alert">연결이 끊겼습니다.<button onClick={reconnect}>다시 연결</button></div>

it('다시 연결을 요청한다', async () => {
  const reconnect = vi.fn()
  render(<ConnectionNotice connected={false} reconnect={reconnect} />)
  expect(screen.getByRole('alert')).toHaveTextContent('연결이 끊겼습니다.')
  await userEvent.click(screen.getByRole('button', { name: '다시 연결' }))
  expect(reconnect).toHaveBeenCalledOnce()
})

export const restoreFocus = (opener: HTMLElement) => {
  requestAnimationFrame(() => opener.focus())
}
